--liquibase formatted sql

-- Configuration every environment starts with: record types, roles and permissions, settings and rules, option
-- lists, and the Person and Entity fields (client field map EXT_CRM_Field_Map_MASTERContact + Design Brief v3.9).
-- Admins change all of it in Setup afterwards; nothing here is fixed in code.

--changeset privateinvest:003-record-types
-- Person and Entity, with the labels of fields that keep a fixed meaning.
--rollback DELETE FROM field_def; DELETE FROM object_def;

--changeset privateinvest:003-roles
-- ADMIN and USER and what each may do.
--rollback DELETE FROM app_role_permission; DELETE FROM app_role;

--changeset privateinvest:003-settings
-- Business settings and the Person and Entity rules (record name, duplicate check, unique ACN/ABN, review queues).
--rollback DELETE FROM app_setting;

--changeset privateinvest:003-option-lists
-- Option lists (picklists) used by the fields.
--rollback DELETE FROM picklist_value; DELETE FROM picklist_set;

--changeset privateinvest:003-fields
-- Field sections and every Person and Entity field.
--rollback DELETE FROM custom_field_def; DELETE FROM custom_field_section;
